@@ -0,0 +1,97 @@
+import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
+import { api } from "@/lib/api";
+import type { Task, TaskStatus } from "@/types/api";
+
+export function useTasks(
+  projectId: string,
+  params?: { page?: number; page_size?: number; status?: TaskStatus; priority?: string; assignee_id?: string }
+) {
+  return useQuery({
+    queryKey: ["tasks", projectId, params],
+    queryFn: () => api.listTasks(projectId, params),
+  });
+}
+
+export function useTask(taskId: string) {
+  return useQuery({
+    queryKey: ["task", taskId],
+    queryFn: () => api.getTask(taskId),
+    enabled: !!taskId,
+  });
+}
+
+export function useMyTasks(params?: { page?: number; page_size?: number; sort_by?: string }) {
+  return useQuery({
+    queryKey: ["myTasks", params],
+    queryFn: () => api.listMyTasks(params),
+  });
+}
+
+export function useCreateTask() {
+  const queryClient = useQueryClient();
+  return useMutation({
+    mutationFn: ({ projectId, data }: { projectId: string; data: Partial<Task> }) =>
+      api.createTask(projectId, data),
+    onSuccess: (_data, variables) => {
+      queryClient.invalidateQueries({ queryKey: ["tasks", variables.projectId] });
+    },
+  });
+}
+
+export function useUpdateTask() {
+  const queryClient = useQueryClient();
+  return useMutation({
+    mutationFn: ({ taskId, data }: { taskId: string; data: Partial<Task> }) =>
+      api.updateTask(taskId, data),
+    onSuccess: (_data, variables) => {
+      queryClient.invalidateQueries({ queryKey: ["task", variables.taskId] });
+      queryClient.invalidateQueries({ queryKey: ["tasks"] });
+    },
+  });
+}
+
+export function useDeleteTask() {
+  const queryClient = useQueryClient();
+  return useMutation({
+    mutationFn: ({ taskId, projectId }: { taskId: string; projectId: string }) =>
+      api.deleteTask(taskId),
+    onSuccess: (_data, variables) => {
+      queryClient.invalidateQueries({ queryKey: ["tasks", variables.projectId] });
+    },
+  });
+}
+
+export function useTransitionTaskStatus() {
+  const queryClient = useQueryClient();
+  return useMutation({
+    mutationFn: ({ taskId, status }: { taskId: string; status: TaskStatus }) =>
+      api.transitionTaskStatus(taskId, status),
+    onSuccess: (_data, variables) => {
+      queryClient.invalidateQueries({ queryKey: ["task", variables.taskId] });
+      queryClient.invalidateQueries({ queryKey: ["tasks"] });
+      queryClient.invalidateQueries({ queryKey: ["myTasks"] });
+    },
+  });
+}
+
+export function useAddTaskDependency() {
+  const queryClient = useQueryClient();
+  return useMutation({
+    mutationFn: ({ taskId, dependsOnTaskId }: { taskId: string; dependsOnTaskId: string }) =>
+      api.addTaskDependency(taskId, dependsOnTaskId),
+    onSuccess: (_data, variables) => {
+      queryClient.invalidateQueries({ queryKey: ["task", variables.taskId] });
+    },
+  });
+}
+
+export function useRemoveTaskDependency() {
+  const queryClient = useQueryClient();
+  return useMutation({
+    mutationFn: ({ taskId, depId }: { taskId: string; depId: string }) =>
+      api.removeTaskDependency(taskId, depId),
+    onSuccess: (_data, variables) => {
+      queryClient.invalidateQueries({ queryKey: ["task", variables.taskId] });
+    },
+  });
+}
