    update as update_vendor,
)
from src.backend.models.vendor import Vendor
from src.backend.schemas.vendor import VendorCreate, VendorUpdate


def list_vendors_service(
    db: Session,
    page: int = 1,
    page_size: int = 20,
    q: str | None = None,
    include_inactive: bool = False,
) -> tuple[list[Vendor], int, int, int]:
    items, total = list_vendors(db, page, page_size, q, include_inactive)
    return items, total, page, page_size


def create_vendor_service(
    db: Session,
    data: VendorCreate,
    actor_id: uuid.UUID | None,
) -> Vendor:
    vendor = create_vendor(
        db,
        name=data.name,
        code=data.code,
        primary_email=data.primary_email,
        address=data.address,
        city=data.city,
        state=data.state,
        pincode=data.pincode,
        country=data.country,
        gst_number=data.gst_number,
        primary_phone=data.primary_phone,
        rating=data.rating,
        notes=data.notes,
    )

    create_entry(
        db,
        action="vendor.create",
        entity_type="vendor",
        entity_id=vendor.id,
        user_id=actor_id,
        after_json={
            "id": str(vendor.id),
            "name": vendor.name,
            "code": vendor.code,
            "primary_email": vendor.primary_email,
        },
    )

    return vendor


def get_vendor_service(db: Session, vendor_id: uuid.UUID) -> Vendor | None:
    return get_vendor_by_id(db, vendor_id)


def update_vendor_service(
    db: Session,
    vendor_id: uuid.UUID,
    data: VendorUpdate,
    actor_id: uuid.UUID | None,
) -> Vendor | None:
    vendor = get_vendor_by_id(db, vendor_id)
    if not vendor:
        return None

    before_json = {
        "name": vendor.name,
        "code": vendor.code,
        "primary_email": vendor.primary_email,
    }

    if data.name is not None:
        vendor.name = data.name
    if data.code is not None:
        vendor.code = data.code
    if data.address is not None:
        vendor.address = data.address
    if data.city is not None:
        vendor.city = data.city
    if data.state is not None:
        vendor.state = data.state
    if data.pincode is not None:
        vendor.pincode = data.pincode
    if data.country is not None:
        vendor.country = data.country
    if data.gst_number is not None:
        vendor.gst_number = data.gst_number
    if data.primary_email is not None:
        vendor.primary_email = data.primary_email
    if data.primary_phone is not None:
        vendor.primary_phone = data.primary_phone
    if data.rating is not None:
        vendor.rating = data.rating
    if data.notes is not None:
        vendor.notes = data.notes
    if data.is_active is not None:
        vendor.is_active = data.is_active

    update_vendor(db, vendor)

    after_json = {
        "name": vendor.name,
        "code": vendor.code,
        "primary_email": vendor.primary_email,
    }

    create_entry(
        db,
        action="vendor.update",
        entity_type="vendor",
        entity_id=vendor.id,
        user_id=actor_id,
        before_json=before_json,
        after_json=after_json,
    )

    return vendor


def soft_delete_vendor_service(
    db: Session,
    vendor_id: uuid.UUID,
    actor_id: uuid.UUID | None,
) -> bool:
    vendor = get_vendor_by_id(db, vendor_id)
    if not vendor:
        return False

    before_json = {"deleted_at": None}

    soft_delete_vendor(db, vendor)

    after_json = {"deleted_at": str(vendor.deleted_at)}

    create_entry(
        db,
        action="vendor.delete",
        entity_type="vendor",
        entity_id=vendor.id,
        user_id=actor_id,
        before_json=before_json,
        after_json=after_json,
    )

    return True

